package ai.learnharness.mobile;

import android.content.Context;import android.database.Cursor;import android.net.Uri;import android.provider.DocumentsContract;import android.provider.DocumentsContract.Document;import android.util.AtomicFile;
import org.json.*;import java.io.*;import java.nio.charset.StandardCharsets;import java.nio.file.Files;import java.util.*;

/** Only descendants enumerated from a user-selected persisted SAF tree become note grants. */
final class FolderDocuments {
 static final Object LOCK=new Object();
 static boolean sameDocument(Uri a,Uri b,boolean tree){if(!Objects.equals(a.getAuthority(),b.getAuthority()))return false;try{return (tree?DocumentsContract.getTreeDocumentId(a):DocumentsContract.getDocumentId(a)).equals(tree?DocumentsContract.getTreeDocumentId(b):DocumentsContract.getDocumentId(b));}catch(IllegalArgumentException unsupported){return a.equals(b);}}
 private static File registry(Context c){return new File(c.getNoBackupFilesDir(),"document-grants.json");}
 private static JSONObject grants(Context c)throws Exception{File f=registry(c);return f.isFile()?new JSONObject(new String(Files.readAllBytes(f.toPath()),StandardCharsets.UTF_8)):new JSONObject();}
 private static void save(Context c,JSONObject all)throws Exception{AtomicFile a=new AtomicFile(registry(c));FileOutputStream out=null;try{out=a.startWrite();out.write(all.toString().getBytes(StandardCharsets.UTF_8));a.finishWrite(out);}catch(Exception e){if(out!=null)a.failWrite(out);throw e;}}
 private static String[] parts(String relative)throws IOException{if(relative.startsWith("/")||relative.contains("\\")||relative.contains(":")||relative.matches(".*[\\x00-\\x1f].*"))throw new IOException("Invalid subject path");if(relative.isEmpty())return new String[0];String[] parts=relative.split("/",-1);for(String p:parts)if(p.isEmpty()||p.equals(".")||p.equals("..")||p.endsWith(".")||p.endsWith(" "))throw new IOException("Invalid subject path");if(parts.length>32)throw new IOException("Subject path too deep");return parts;}
 private static Uri root(JSONObject all,String handle)throws Exception{JSONObject grant=all.optJSONObject(handle);if(grant==null||!grant.optBoolean("directory"))throw new IOException("Folder permission missing. Relink the subject");Uri tree=Uri.parse(grant.getString("uri"));if(!DocumentsContract.isTreeUri(tree))throw new IOException("Choose a document tree");return tree;}
 private static Uri resolve(Context c,Uri tree,String relative)throws Exception{Uri current=DocumentsContract.buildDocumentUriUsingTree(tree,DocumentsContract.getTreeDocumentId(tree));for(String name:parts(relative)){Uri children=DocumentsContract.buildChildDocumentsUriUsingTree(tree,DocumentsContract.getDocumentId(current));String found=null;try(Cursor cur=c.getContentResolver().query(children,new String[]{Document.COLUMN_DOCUMENT_ID,Document.COLUMN_DISPLAY_NAME},null,null,null)){if(cur==null)throw new IOException("Folder unavailable");int count=0;while(cur.moveToNext()){if(++count>25000)throw new IOException("Directory exceeds scan limit");if(name.equals(cur.getString(1))){if(found!=null)throw new IOException("Ambiguous provider filename. Select a different folder");found=cur.getString(0);}}}if(found==null)throw new IOException("Note moved or unavailable. Refresh or relink the folder");current=DocumentsContract.buildDocumentUriUsingTree(tree,found);}return current;}
 static Uri boundUri(Context c,JSONObject grant)throws Exception{Uri uri=Uri.parse(grant.getString("uri"));if(grant.has("rootHandle")){synchronized(LOCK){JSONObject all=grants(c);Uri resolved=resolve(c,root(all,grant.getString("rootHandle")),grant.getString("relative"));if(!resolved.equals(uri))throw new IOException("The original note identity changed. Relink it before writing");}}return uri;}
 private static JSONObject metadata(Context c,Uri uri)throws Exception{try(Cursor cur=c.getContentResolver().query(uri,new String[]{Document.COLUMN_DISPLAY_NAME,Document.COLUMN_MIME_TYPE,Document.COLUMN_FLAGS,Document.COLUMN_SIZE},null,null,null)){if(cur==null||!cur.moveToFirst())throw new IOException("Document unavailable");return new JSONObject().put("name",cur.getString(0)).put("directory",Document.MIME_TYPE_DIR.equals(cur.getString(1))).put("flags",cur.getInt(2)).put("size",cur.isNull(3)?0:cur.getLong(3));}}
 static JSONObject request(Context c,JSONObject request)throws Exception{return DocumentGrantStore.locked(c,()->requestLocked(c,request));}
 private static JSONObject requestLocked(Context c,JSONObject request)throws Exception{synchronized(LOCK){String handle=request.getString("handle"),relative=request.optString("relative"),op=request.getString("operation");if(!handle.matches("grant_[a-f0-9]{32}"))throw new IOException("Folder permission missing");parts(relative);JSONObject all=grants(c);Uri tree=root(all,handle);
  if(op.equals("list")){Uri dir=resolve(c,tree,relative);if(!metadata(c,dir).getBoolean("directory"))throw new IOException("Selected path is not a directory");Uri children=DocumentsContract.buildChildDocumentsUriUsingTree(tree,DocumentsContract.getDocumentId(dir));JSONArray entries=new JSONArray();try(Cursor cur=c.getContentResolver().query(children,new String[]{Document.COLUMN_DOCUMENT_ID,Document.COLUMN_DISPLAY_NAME,Document.COLUMN_MIME_TYPE,Document.COLUMN_SIZE},null,null,null)){if(cur==null)throw new IOException("Folder provider unavailable");while(cur.moveToNext()){if(entries.length()>=25000)throw new IOException("Directory exceeds 25,000 entries. Choose a smaller folder");entries.put(new JSONObject().put("name",cur.getString(1)).put("identity",cur.getString(0)).put("directory",Document.MIME_TYPE_DIR.equals(cur.getString(2))).put("size",cur.isNull(3)?0:cur.getLong(3)));}}return new JSONObject().put("entries",entries);}
  Uri document;
  if(op.equals("create")){String[] segments=parts(relative);if(segments.length==0||!relative.toLowerCase(Locale.ROOT).endsWith(".md"))throw new IOException("Choose a Markdown filename");String name=segments[segments.length-1],parent=relative.contains("/")?relative.substring(0,relative.lastIndexOf('/')):"";Uri dir=resolve(c,tree,parent);if((metadata(c,dir).getInt("flags")&Document.FLAG_DIR_SUPPORTS_CREATE)==0)throw new IOException("Folder is read-only");boolean exists=true;try{resolve(c,tree,relative);}catch(IOException missing){if(missing.getMessage()!=null&&missing.getMessage().startsWith("Note moved"))exists=false;else throw missing;}if(exists)throw new IOException("A note already exists at that path");byte[] bytes=request.optString("text").getBytes(StandardCharsets.UTF_8);if(bytes.length>5*1024*1024)throw new IOException("Note exceeds 5 MiB");document=DocumentsContract.createDocument(c.getContentResolver(),dir,"text/markdown",name);if(document==null||!name.equals(metadata(c,document).getString("name")))throw new IOException("Provider returned a different filename; review the folder before retrying");try(OutputStream out=c.getContentResolver().openOutputStream(document,"wt")){if(out==null)throw new IOException("Provider did not open the new note");out.write(bytes);}try(InputStream in=c.getContentResolver().openInputStream(document)){ByteArrayOutputStream check=new ByteArrayOutputStream();if(in==null)throw new IOException("New note unavailable");byte[] buffer=new byte[8192];int n;while((n=in.read(buffer))!=-1){if(check.size()+n>5*1024*1024)throw new IOException("New note verification exceeds limit");check.write(buffer,0,n);}if(!Arrays.equals(bytes,check.toByteArray()))throw new IOException("Provider did not retain the new note; review before retrying");}
  }else if(op.equals("bind"))document=resolve(c,tree,relative);else throw new IOException("Unsupported folder action");
  JSONObject meta=metadata(c,document);if(meta.getBoolean("directory")||meta.optLong("size")>5*1024*1024)throw new IOException("Choose a Markdown note up to 5 MiB");String child="grant_"+UUID.randomUUID().toString().replace("-","");for(Iterator<String> it=all.keys();it.hasNext();){String key=it.next();JSONObject g=all.optJSONObject(key);if(g!=null&&!g.optBoolean("directory")&&sameDocument(document,Uri.parse(g.optString("uri")),false)){child=key;break;}}
  boolean writable=(meta.getInt("flags")&Document.FLAG_SUPPORTS_WRITE)!=0;JSONObject prior=all.optJSONObject(child);if(prior==null||prior.has("rootHandle"))all.put(child,new JSONObject().put("uri",document.toString()).put("name",meta.getString("name")).put("writable",writable).put("rootHandle",handle).put("relative",relative));else writable=prior.optBoolean("writable");save(c,all);return new JSONObject().put("document",new JSONObject().put("handle",child).put("name",meta.getString("name")).put("kind","android").put("writable",writable));
 }}
}
